const D=[{"t":"Kamloops to Stump Lake","d":"Roll out of Kamloops and south into the grasslands to Stump Lake. The last big resupply is in Kamloops, and water is scarce until Douglas Lake, so fill up and carry about a day and a half.","a":0,"b":62.22,"st":[[0,"District Bicycle Co.","Start of the loop. Full service bike shop.","s"],[248.24,"Kamloops","Restaurants, shops and resupply, about 1.6 km off the route. Last big resupply before Douglas Lake.","p",50.67434,-120.32724],[62.22,"Stump Lake Recreation Site","Tonight's camp, a recreation site by the lake.","e",50.35154,-120.37234]],"km":62.2,"up":0,"dn":0},{"t":"Stump Lake to Salmon Lake","d":"Ride past Peter Hope Lake and Glimpse Lake and through Douglas Lake Ranch country, with a resupply and water stop at Douglas Lake. Then camp at Salmon Lake, where there is a store and tap water.","a":62.22,"b":138.45,"st":[[62.22,"Stump Lake Recreation Site","Start of the day.","s",50.35154,-120.37234],[74.53,"Peter Hope Lake North Rec Site","Recreation site. Peter Hope Rd is one of the two hardest climbs of the route.","c"],[85.29,"Glimpse Lake North Rec Site","Recreation site.","c"],[116.74,"Douglas Lake Village and General Store","Basic resupply and water. Opening hours not confirmed (one rider found it closed in 2020), so Salmon Lake is the backup for water.","p",50.16371,-120.19745],[138.45,"Salmon Lake RV Resort","Tonight's camp. Small store, camping, and water from the tap at the side of the store.","e",50.2738,-120.00227]],"km":76.2,"up":0,"dn":0},{"t":"Salmon Lake to Robbins Range","d":"Pass Monte Lake for food and resupply, then start the Robbins Range Rd section toward Kamloops and camp near the Campbell Lake turn-off. The camp is not fixed yet.","a":138.45,"b":196.5,"st":[[138.45,"Salmon Lake RV Resort","Start of the day.","s",50.2738,-120.00227],[147.02,"Monte Lake FSR","Wild camping options along this section of road. A backup camp if you ride shorter on day 2.","c"],[174.22,"Monte Lake Store and The Local","Basic resupply and great food (food truck). Last resupply before Kamloops.","p"],[196.5,"Campbell Lake Rec Site","Possible camp for night 3: a recreation site with 31 sites and pit toilets, about 6 km off the route by road (Campbell Range Rd and Scuitto Lake FSR). Drinking water not confirmed, so bring your own.","c",50.5513,-120.09755],[196.5,"Night 3 camp (to choose)","Camp not fixed yet. Pick Campbell Lake Rec Site (see above) or find a wild camp near here.","e"]],"km":58.1,"up":0,"dn":0},{"t":"Robbins Range to Kamloops","d":"Finish Robbins Range Rd, drop through Barnhartvale and ride Campbell Creek Rd back into Kamloops.","a":196.5,"b":249.75,"st":[[196.5,"Night 3 camp (to choose)","Start of the day.","s"],[249.75,"District Bicycle Co.","Loop complete. Full service bike shop.","e"]],"km":53.2,"up":0,"dn":0}];
